import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Project brief","description":"","frontmatter":{},"headers":[],"relativePath":"project/index.md","filePath":"project/index.md","lastUpdated":1794374806000}'),n={name:"project/index.md"};function o(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="project-brief" tabindex="-1">Project brief <a class="header-anchor" href="#project-brief" aria-label="Permalink to &quot;Project brief&quot;">​</a></h1><p><strong>Ordo Knowledge Lab · IS373 · documentation and contract-review phase.</strong></p><p>Build a portable research library that gains processing capabilities without losing control of its evidence. UFO reports are the first teaching domain, not a permanent restriction on the engine. Build from carefully selected Ordo behaviors rather than importing the entire business platform or starting without its useful code.</p><h2 id="user-experience" tabindex="-1">User experience <a class="header-anchor" href="#user-experience" aria-label="Permalink to &quot;User experience&quot;">​</a></h2><p>An instructor imports sources, reviews ambiguous identities and claims, and publishes a revision. A learner asks a question in a streaming interface and opens the exact evidence behind the answer. The same published library opens on another machine even when a processing plugin is unavailable.</p><p>The central principle is <strong>canonical identity, not canonical truth</strong>. One incident may have conflicting accounts. Resolving its identity does not authorize erasing disagreement.</p><h2 id="current-direction" tabindex="-1">Current direction <a class="header-anchor" href="#current-direction" aria-label="Permalink to &quot;Current direction&quot;">​</a></h2><p>Rust owns state and coordination. Workers use language-neutral contracts and may be Rust, Swift or another appropriate implementation. CPU/NVIDIA/Apple capabilities are optional. The data is portable; jobs are durable and observable. Identity resolution, provenance, review and recovery take precedence over infrastructure complexity.</p><p>The hosted API and workers follow <a href="./../engineering/twelve-factor">twelve-factor requirements</a>, with a private Rust store as their durable backing service. Local authoring may embed that store as an explicitly stateful appliance. We do not call a database stateless merely because it runs in a container.</p><h2 id="what-to-review-first" tabindex="-1">What to review first <a class="header-anchor" href="#what-to-review-first" aria-label="Permalink to &quot;What to review first&quot;">​</a></h2><p><a href="./../reuse/">Reuse map</a> → <a href="./../reuse/source-audit">source audit</a> → <a href="./system">system</a> → <a href="./knowledge">knowledge</a> → <a href="./../engineering/twelve-factor">factor matrix</a> → <a href="./roadmap">roadmap</a>.</p><p>The <a href="./../engineering/examples">executable examples</a> make specific failure contracts testable. The <a href="./acceptance">requirements</a> describe broader application acceptance that those small labs do not satisfy on their own.</p><h2 id="first-complete-demonstration" tabindex="-1">First complete demonstration <a class="header-anchor" href="#first-complete-demonstration" aria-label="Permalink to &quot;First complete demonstration&quot;">​</a></h2><p>Import synthetic reports containing aliases, two people sharing a name, copied testimony and a contradiction. Repeat the import without duplicate acceptance. Resolve ambiguity, publish a reviewed revision, stream a cited answer, and open the library on Linux without the Mac worker. Inspect what a stopped worker or disconnected browser did and did not preserve.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><p>This repository currently contains documentation, checks and synthetic examples—not the running application. No multi-writer library sync, unrestricted public ingestion, automatic canonical merges, plugin marketplace or production-scale claim is required for the first release. Native video comes later as a bounded capability.</p><p>Portfolio DNS, documentation Pages and the future application host are distinct operations. See <a href="./hosting">hosting</a>, <a href="./decisions">decisions</a>, <a href="./sources">source rules</a> and <a href="./../status">status</a>. This instructor example does not alter course grading or require students to adopt every proposed technology.</p>',17)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
